/* ---------- จับคู่เลนส์กับความต้องการลูกค้า (หน้าบริการลูกค้า ขั้นตอนที่ 1-3) ---------- */
// ขั้นตอนที่ 3 ใช้ชุดตัวเลือกเดียวกับ LENS_DESIGN ที่หลังบ้านเป๊ะ ๆ (ไม่แยกชุดคำศัพท์กันสองที่)
function lensTypeTest(p, key) { return (p.lens_spec || {}).design === key; }
// กรองแบบเข้ม เฉพาะข้อ 3 (โครงสร้างเลนส์) เพราะถ้าเลือก "Single Vision" แล้วเจอโปรเกรสซีฟคือผิดประเภทจริง ๆ
// ถ้าสินค้าไม่มีข้อมูล lens_spec เลย (สินค้าเก่าที่ยังไม่ได้ระบุ) จะไม่ตัดออก กันไม่ให้สินค้าที่ร้านเพิ่มเองหายไปจากรายการ
function lensPassesHardFilter(p, lr) {
  if (lr.lenstype.length) {
    if (!lr.lenstype.some(k => lensTypeTest(p, k))) return false;
  }
  if ((lr.brand || []).length && !lr.brand.includes(p.brand)) return false;
  if ((lr.level || []).length && !lr.level.includes((p.lens_spec || {}).tier)) return false;
  if ((lr.lensIndex || []).length || (lr.coating || []).length || (lr.photochromic || []).length) {
    const vr = lensVariants(p);
    if ((lr.lensIndex || []).length && !vr.some(v => lr.lensIndex.includes(v.index))) return false;
    if ((lr.coating || []).length && !vr.some(v => lr.coating.includes(v.coating))) return false;
    if ((lr.photochromic || []).length && !vr.some(v => lr.photochromic.includes(v.color_change))) return false;
  }
  return true;
}
const lensHasCoatingKey = (p, needle) => lensVariants(p).some(v => (v.coating || '').toLowerCase().includes(needle));
const lensHasColorKey = (p, keys) => lensVariants(p).some(v => keys.includes(v.color_change));
const VISION_MATCH = {
  allrange: p => (p.lens_spec || {}).design === 'progressive',
  fartired: p => ['progressive', 'office', 'anti_fatigue'].includes((p.lens_spec || {}).design),
  glare: p => { const c = (p.lens_spec || {}).coatings || []; return c.includes('ar') || c.includes('polarized') || lensHasColorKey(p, ['polarized', 'mirror']); },
  darklow: p => ((p.lens_spec || {}).coatings || []).includes('ar'),
  blue: p => ((p.lens_spec || {}).coatings || []).includes('blue') || lensHasCoatingKey(p, 'blue'),
  uv: p => { const c = (p.lens_spec || {}).coatings || []; return c.includes('uv400') || c.includes('polarized') || lensHasColorKey(p, ['polarized']); },
  thin: p => lensVariants(p).some(v => { const i = parseFloat(v.index); return !isNaN(i) && i >= 1.60; }),
  durable: p => ((p.lens_spec || {}).coatings || []).includes('hard') || lensVariants(p).some(v => v.coating === 'hard'),
};
const PURPOSE_MATCH = {
  screen: p => ['anti_fatigue', 'office'].includes((p.lens_spec || {}).design) || ((p.lens_spec || {}).coatings || []).includes('blue') || lensHasCoatingKey(p, 'blue'),
  mobile: p => ((p.lens_spec || {}).coatings || []).includes('blue') || lensHasCoatingKey(p, 'blue') || (p.lens_spec || {}).design === 'anti_fatigue',
  read: p => ['office'].includes((p.lens_spec || {}).design),
  drive: p => ((p.lens_spec || {}).coatings || []).includes('polarized') || lensHasColorKey(p, ['polarized', 'mirror']),
  outdoor: p => { const c = (p.lens_spec || {}).coatings || []; return c.includes('photo') || c.includes('polarized') || lensHasColorKey(p, LENS_PHOTO_COLOR_KEYS); },
};
// คะแนนความตรงความต้องการ (ข้อ 1-2) ใช้จัดลำดับเท่านั้น ไม่ใช้ตัดรายการออก เพราะเป็นความต้องการที่ไม่เข้มงวดเท่าโครงสร้างเลนส์
function lensMatchScore(p, lr) {
  let score = 0, total = 0;
  (lr.vision || []).forEach(k => { if (VISION_MATCH[k]) { total++; if (VISION_MATCH[k](p)) score++; } });
  (lr.purpose || []).forEach(k => { if (PURPOSE_MATCH[k]) { total++; if (PURPOSE_MATCH[k](p)) score++; } });
  return { score, total };
}
function lrHasCriteria(lr) { return !!(lr.lenstype.length || lr.vision.length || lr.purpose.length || (lr.brand || []).length || (lr.level || []).length || (lr.lensIndex || []).length || (lr.coating || []).length || (lr.photochromic || []).length); }
const empty = (m, a = '') => `<div class="empty">${m}${a ? `<br><br>${a}` : ''}</div>`;
const fmtP = v => v == null || v === '' ? '-' : (+v > 0 ? '+' : '') + (+v).toFixed(2);
const day = d => d ? new Date(d).toLocaleDateString('th-TH') : '-';
const cartSub = () => S.cart.reduce((n, i) => n + i.price * i.qty, 0);
function discAmt(cfg, base) {
  const v = Math.max(0, +(cfg && cfg.val) || 0);
  const amt = cfg && cfg.type === 'pct' ? base * v / 100 : v;
  return Math.min(base, Math.round(amt));
}
function cartCalc() {
  const frameSub = S.cart.filter(i => i.type === 'frame').reduce((n, i) => n + i.price * i.qty, 0);
  const lensSub = S.cart.filter(i => i.type === 'lens').reduce((n, i) => n + i.price * i.qty, 0);
  const otherSub = S.cart.filter(i => i.type !== 'frame' && i.type !== 'lens').reduce((n, i) => n + i.price * i.qty, 0);
  const discFrameAmt = discAmt(K.discFrame, frameSub);
  const discLensAmt = discAmt(K.discLens, lensSub);
  const sub = frameSub + lensSub + otherSub;
  const discTotal = discFrameAmt + discLensAmt;
  return { frameSub, lensSub, otherSub, discFrameAmt, discLensAmt, sub, discTotal, total: sub - discTotal };
}
const latestRx = cid => db.prescriptions.filter(r => !r.deleted_at && r.customer_id === cid).sort((a, b) => (b.exam_date || b.created_at).localeCompare(a.exam_date || a.created_at))[0];
const rxText = r => r ? `ขวา ${fmtP(r.od_sph)}${r.od_cyl != null ? '/' + fmtP(r.od_cyl) + '×' + (r.od_axis ?? '-') : ''} · ซ้าย ${fmtP(r.os_sph)}${r.os_cyl != null ? '/' + fmtP(r.os_cyl) + '×' + (r.os_axis ?? '-') : ''}` : 'ยังไม่มีค่าสายตา';
