    const grp = (types, title) => { const l = ps.filter(p => types.includes(p.product_type)).sort((a, b) => tag(b) - tag(a)); return `<h2 class="gap">${title}</h2><div class="cards">${l.map(card).join('') || empty('ยังไม่มี' + title)}</div>`; };
